/// sequences stay literal (legacy text).
String _unescapeSlugPart(String part) => part.replaceAllMapped(
  _slugEscape,
  (m) => switch (m.group(1)!.toUpperCase()) {
    '25' => '%',
    '2D' => '-',
    '2F' => '/',
    '5C' => r'\',
    '3A' => ':',
    _ => m.group(0)!,
  },
);

