      final env = MemoryExecutionEnv(cwd: '/work', shell: shell);
      (await env.writeFile('/work/a-file', 'x')).getOrThrow();
      final error = await launchMailboxWake(
        env: env,
        cwd: '/work/a-file',
        sessionId: 'sess-1',
