      final shell = _RecordingShell();
      final env = MemoryExecutionEnv(cwd: '/work', shell: shell);
      (await env.createDir('/Users/y/_w/postal-nl', recursive: true))
          .getOrThrow();
      final error = await launchMailboxWake(
        env: env,
        wakeExecutable: '/usr/local/bin/fa',
